from pathlib import Path
import argparse,hashlib,json,shutil,sys
from build_release import ROOT,archive,write,snapshot,manifest
from scan import scan_items,tree
def main():
 p=argparse.ArgumentParser();p.add_argument('--attempt',required=True);a=p.parse_args()
 out=ROOT/'release'/a.attempt
 if out.exists():raise SystemExit('ATTEMPT_EXISTS')
 consumer=out/'consumer';consumer.mkdir(parents=True)
 build=json.loads((ROOT/'engineering'/'HUMAN-BUILD.json').read_text(encoding='utf-8'))
 exe=Path(build['artifact']);blob=exe.read_bytes();digest=hashlib.sha256(blob).hexdigest()
 assert digest==build['artifact_sha256']
 shutil.copyfile(exe,consumer/'Manus-Connection-Kit-Setup.exe')
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Start here — Manus Connection Kit</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;background:#f2f5f8;color:#172b3a;font:18px/1.65 system-ui,sans-serif}main{max-width:820px;margin:36px auto;padding:40px;background:white;border-radius:20px}h1{line-height:1.2;font-size:36px}h2{font-size:24px;margin-top:32px}.tag{color:#526b80}li{margin:12px 0}.note{padding:18px;background:#edf5fa;border-radius:12px}code{font-size:12px;word-break:break-all}small{font-size:14px}a{color:#145b94}</style><main><p class="tag">MANUS CONNECTION KIT · EASY HUMAN MODE · 0.2.0-human.1</p><h1>Your local Manus connection,<br>in a few visible steps.</h1><p>This folder contains this page and one Windows installer. You do not need Python or a terminal.</p><ol><li>Open <b>Manus-Connection-Kit-Setup.exe</b>.</li><li>Choose <b>1. Install / Update</b>. It installs for your Windows account; administrator rights are not normally needed.</li><li>Enter your own Manus API key in the masked field, then choose <b>2. Save Key</b>. The key stays encrypted on this Windows account. Never paste it into chat.</li><li>Choose <b>3. Test Connection</b>. <b>PASS</b> means the account identity check succeeded. <b>BLOCKED</b> means a key, account or connection step still needs attention.</li></ol><p class="note">Test Connection checks identity only. It does not create a paid Manus task. Creating tasks later still requires a fresh owner-authorized grant.</p><h2>Connect a compatible local AI client</h2><p>Choose <b>Create AI Client Connection File</b>, then import that file into a client supporting local MCP stdio. The file contains no API key. Automatic import into every AI client is not verified.</p><p>Ordinary ChatGPT, Claude and Gemini web chat have no proven direct bridge to this local app. Installing this kit does not add one.</p><h2>Update, rollback or uninstall</h2><p>Close connected AI clients. Open a newer trusted setup EXE and choose Install / Update. For a changed installation, paste the expected SHA-256 from the separately trusted release receipt when asked. The installer tests before activation, keeps a backup and restores it if activation fails. Use Rollback to return to that backup.</p><p>Use Uninstall to remove the application. Your private journal and encrypted key are retained. Remove Saved Key is a separate explicit action. Keep the original setup file to reopen maintenance if needed.</p><h2>Before sharing or selling</h2><p>This is an unsigned private evaluation candidate for Windows x64. Windows may show an OS confirmation; publisher identity and SmartScreen reputation are not established. Commercial license and support terms remain unresolved. A successful synthetic test is not live auth or a nontechnical-user usability study.</p><small>Installer SHA-256: <code>EXE_HASH</code>. The trusted external receipt covers the complete ZIP. A hash stored alongside an untrusted download alone does not prove its publisher. No automatic updates, background service or remote tunnel is installed.</small></main></html>'''.replace('EXE_HASH',digest)
 (consumer/'START-HERE.html').write_text(page,encoding='utf-8')
 scan=scan_items(tree(consumer));write(out/'SECRET-SCAN.json',scan)
 if scan['findings']:raise SystemExit('SECRET_REVIEW_REQUIRED')
 artifact=archive(consumer,out/'manus-connection-kit-0.2.0-human.1.zip')
 receipt={'mission_id':'AGY-MCK-020-20261015','mode':'human','build_attempt':a.attempt,'artifact':artifact,'installer':{'file':'Manus-Connection-Kit-Setup.exe','sha256':digest,'size':len(blob)},'PACKAGE_BUILT':'PASS','INSTALL_TEST_PASS':'UNVERIFIED','LOCAL_FUNCTION_PASS':'UNVERIFIED','AUTH_VERIFIED':'UNVERIFIED','LIVE_EXECUTION_PASS':'UNVERIFIED','INTEGRATED_PASS':'UNVERIFIED','visual_usability':'UNVERIFIED','commercial_ready':'BLOCKED_LICENSE_SUPPORT_UNRESOLVED','publisher_signature':'UNAVAILABLE_UNSIGNED'}
 write(out/'BUILD-RECEIPT.json',receipt)
 (out/'SHA256SUMS.txt').write_text(artifact['sha256']+'  '+artifact['file']+'\n'+digest+'  Manus-Connection-Kit-Setup.exe\n',encoding='utf-8')
 print(json.dumps(receipt))
if __name__=='__main__':main()
